// Original v1 teaching diagrams. Keep this renderer stable for frozen v1 sources.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const leg=(side,y,kneeY,footY,pair)=>{const sign=side==='left'?-1:1,x=160+sign*30,knee=160+sign*57,foot=160+sign*86;return `<g data-walking-leg="${side}-${pair}" data-pair="${pair}"><path d="M${x} ${y}L${knee} ${kneeY}L${foot} ${footY}" fill="none" stroke="#245447" stroke-width="6" stroke-linecap="round"/><circle cx="${knee}" cy="${kneeY}" r="4" fill="#fffdf5" stroke="#245447" stroke-width="2"/></g>`;};
function antennae(y=40){return `<g data-appendage="antennae" fill="none" stroke="#a56821" stroke-width="2.5" stroke-dasharray="4 3"><path d="M148 ${y}Q140 ${y-18} 123 ${y-25}"/><path d="M172 ${y}Q180 ${y-18} 197 ${y-25}"/></g>`;}
function ladybird(view){const legs=Array.from({length:3},(_,i)=>['left','right'].map(side=>leg(side,88+i*17,69+i*35,58+i*48,i+1)).join('')).join('');return `${antennae(42)}${legs}<ellipse cx="160" cy="54" rx="24" ry="22" fill="#415342" stroke="#183f39" stroke-width="2"/><ellipse cx="160" cy="105" rx="36" ry="35" fill="#d4b986" stroke="#183f39" stroke-width="2"/>${view==='body'?'<path d="M160 98C89 91 92 209 160 216Z" fill="#d5846d" stroke="#183f39" stroke-width="3"/><path d="M160 98C231 91 228 209 160 216Z" fill="#d5846d" stroke="#183f39" stroke-width="3"/><path d="M160 102V213" stroke="#183f39" stroke-width="3"/><text x="160" y="240" text-anchor="middle" font-size="13" fill="#183f39">Paired hard wing cases meet here</text><path d="M160 226V190" stroke="#183f39" stroke-width="1.5"/>':'<ellipse cx="160" cy="171" rx="40" ry="48" fill="#dfd4b7" stroke="#183f39" stroke-width="2"/><path d="M130 150h60m-65 17h70m-62 17h64" stroke="#9b8a68" stroke-width="1.5"/><text x="160" y="240" text-anchor="middle" font-size="13" fill="#183f39">3 pairs of jointed walking legs</text>'}`;}
function woodlouse(view){const legs=Array.from({length:7},(_,i)=>['left','right'].map(side=>leg(side,79+i*18,83+i*18,91+i*18,i+1)).join('')).join('');return `${antennae(48)}${legs}<ellipse cx="160" cy="53" rx="25" ry="20" fill="#b4bfad" stroke="#183f39" stroke-width="2"/><rect x="125" y="68" width="70" height="139" rx="20" fill="${view==='body'?'#b4bfad':'#dfd4b7'}" stroke="#183f39" stroke-width="2"/>${view==='body'?Array.from({length:7},(_,i)=>`<path d="M${i===0?136:129} ${77+i*18}Q160 ${87+i*18} ${i===0?184:191} ${77+i*18}L${i===6?182:191} ${91+i*18}Q160 ${102+i*18} ${i===6?138:129} ${91+i*18}Z" fill="${i%2?'#b4bfad':'#cbd1bd'}" stroke="#596d59" stroke-width="1.5"/>`).join(''):'<path d="M160 75V198" stroke="#9b8a68" stroke-width="2"/>'}<text x="160" y="240" text-anchor="middle" font-size="13" fill="#183f39">${view==='body'?'Flattened body, overlapping plates':'7 pairs of jointed walking legs'}</text>`;}
function snail(view){return `<path d="M48 191Q74 172 130 181L233 173Q251 169 253 150L252 129Q268 138 273 173Q283 183 291 192Z" fill="#b2c39d" stroke="#245447" stroke-width="3"/><path d="M52 195Q162 205 291 195L281 207H63Z" fill="#d8c995" stroke="#245447" stroke-width="2"/><g data-appendage="tentacles" fill="none" stroke="#a56821" stroke-width="3"><path d="M253 136Q250 110 236 96M260 140Q270 118 279 105M263 160q18-8 25-4M253 157q-12-7-18-3"/></g><circle cx="236" cy="96" r="3" fill="#a56821"/><circle cx="279" cy="105" r="3" fill="#a56821"/>${view==='body'?'<circle cx="143" cy="136" r="53" fill="#e1c58e" stroke="#715f3e" stroke-width="3"/><path d="M180 157C207 118 157 70 121 105C90 137 124 171 151 154C173 140 159 113 140 123C126 130 135 145 146 138" fill="none" stroke="#715f3e" stroke-width="4"/>':'<path d="M93 173Q95 91 154 87Q199 89 203 176" fill="#eee4c6" stroke="#9a8963" stroke-width="2" stroke-dasharray="5 4"/><text x="160" y="73" text-anchor="middle" font-size="12" fill="#52675e">Shell shown as a light outline</text>'}<path d="M160 228V204" stroke="#245447" stroke-width="1.5"/><text x="160" y="246" text-anchor="middle" font-size="12" fill="#183f39">Broad muscular foot, not a jointed leg</text>`;}
function wormRings(){return Array.from({length:16},(_,i)=>{const u=(i+1)/17,points=u<=.5?[[40,149],[70,104],[108,118],[147,145]]:[[147,145],[186,172],[224,179],[278,139]],t=u<=.5?u*2:(u-.5)*2,q=1-t,x=q*q*q*points[0][0]+3*q*q*t*points[1][0]+3*q*t*t*points[2][0]+t*t*t*points[3][0],y=q*q*q*points[0][1]+3*q*q*t*points[1][1]+3*q*t*t*points[2][1]+t*t*t*points[3][1],dx=3*q*q*(points[1][0]-points[0][0])+6*q*t*(points[2][0]-points[1][0])+3*t*t*(points[3][0]-points[2][0]),dy=3*q*q*(points[1][1]-points[0][1])+6*q*t*(points[2][1]-points[1][1])+3*t*t*(points[3][1]-points[2][1]),length=Math.hypot(dx,dy),nx=-dy/length,ny=dx/length,f=n=>n.toFixed(2);return `<path d="M${f(x-nx*16)} ${f(y-ny*16)}Q${f(x+dx/length*3)} ${f(y+dy/length*3)} ${f(x+nx*16)} ${f(y+ny*16)}" fill="none" stroke="#775b45" stroke-width="2"/>`;}).join('');}
function worm(view){return `<path d="M40 149C70 104 108 118 147 145S224 179 278 139" fill="none" stroke="#775b45" stroke-width="39" stroke-linecap="round"/><path d="M40 149C70 104 108 118 147 145S224 179 278 139" fill="none" stroke="#c99d83" stroke-width="34" stroke-linecap="round"/>${wormRings()}<text x="160" y="215" text-anchor="middle" font-size="14" fill="#183f39">${view==='body'?'Long ringed body; no external coiled shell':'No jointed walking legs'}</text><text x="160" y="238" text-anchor="middle" font-size="12" fill="#52675e">Ring count is not needed for this key</text>`;}
const descriptions={snail:'A soft adult body above a broad muscular foot, with a coiled shell. Unjointed tentacles are feelers. There are zero jointed walking legs.',worm:'A long adult body with ring-like divisions, no external coiled shell and zero jointed walking legs. Ring count is not part of the key.',ladybird:'An adult body with paired hard wing cases meeting in the middle. Exactly six jointed walking legs form three pairs, attached at the thorax. Two thin ochre dashed antennae are feelers, not walking legs.',woodlouse:'An adult flattened body with overlapping plates. Exactly fourteen jointed walking legs form seven pairs. Thin ochre dashed antennae are not legs; other appendages are outside this walking-leg diagram.'};
export function bodyDiagram(source,view='body'){const d=source?.drawing;if(d?.version!==1||!Object.hasOwn(descriptions,d.kind))return '<p>This saved diagram version cannot be shown here. Its original work is retained.</p>';const detail=view==='detail',caption=detail?d.kind==='ladybird'||d.kind==='woodlouse'?'Walking-leg underside teaching view · same pictured adult':'Walking-leg body teaching detail · same pictured adult':'Body teaching view · pictured adult';return `<figure class="body-diagram" data-drawing-version="1" data-drawing-kind="${d.kind}" data-drawing-view="${detail?'detail':'body'}"><svg viewBox="0 0 320 265" role="img" aria-label="${esc(caption+'. '+(typeof (detail?source.detailText:source.bodyText)==='string'?(detail?source.detailText:source.bodyText):descriptions[d.kind]))}"><rect x="1" y="1" width="318" height="263" rx="18" fill="#f0f4e9"/>${({snail,worm,ladybird,woodlouse}[d.kind])(detail?'detail':'body')}</svg><figcaption>${caption}${d.kind==='ladybird'||d.kind==='woodlouse'?'<span>Jointed walking legs: thick green strokes with visible joints. Feelers: thin ochre strokes. Other appendages are outside this walking-leg count.</span>':''}</figcaption></figure>`;}
